package com.bookstore.service;
import com.bookstore.entity.Book; import com.bookstore.repository.BookRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class BookService { private final BookRepository repo; public BookService(BookRepository r){repo=r;} public List<Book> all(String q,String category){if(q!=null&&!q.isBlank()) return repo.findByNameContainingIgnoreCaseOrAuthorContainingIgnoreCase(q,q); if(category!=null&&!category.isBlank()) return repo.findByCategoryIgnoreCase(category); return repo.findAll();} public Book get(Long id){return repo.findById(id).orElseThrow();} public Book save(Book b){return repo.save(b);} public void delete(Long id){repo.deleteById(id);} public long count(){return repo.count();} public long lowStock(){return repo.countByStockLessThan(5);} public List<Book> allRaw(){return repo.findAll();}}
